targets.expr:
min by (job, switch, interface) (
  arista_transceiver_rx_power_dbm{job=~"$job",switch=~"$switch",interface=~"$interface"}
    - on(job, switch, interface) group_left
      arista_transceiver_rx_power_threshold_dbm{job=~"$job",switch=~"$switch",interface=~"$interface",level="low_warn"}
)
and on(job, switch, interface)
  arista_interface_link_up{job=~"$job",switch=~"$switch",interface=~"$interface"} == 1

min by (job, switch, interface) (
  arista_transceiver_rx_power_dbm{job=~"$job",switch=~"$switch",interface=~"$interface"}
    - on(job, switch, interface) group_left
      arista_transceiver_rx_power_threshold_dbm{job=~"$job",switch=~"$switch",interface=~"$interface",level="low_warn"}
)
and on(job, switch, interface)
  arista_interface_link_up{job=~"$job",switch=~"$switch",interface=~"$interface"} == 1

max by (job, switch, slot) (
  arista_transceiver_temperature_celsius{job=~"$job",switch=~"$switch",interface=~"$interface"}
    * on(job, switch, interface) group_left(slot)
      arista_transceiver_info{job=~"$job",switch=~"$switch",interface=~"$interface"}
)

max by (job, switch, slot) (
  arista_transceiver_voltage_volts{job=~"$job",switch=~"$switch",interface=~"$interface"}
    * on(job, switch, interface) group_left(slot)
      arista_transceiver_info{job=~"$job",switch=~"$switch",interface=~"$interface"}
)
